using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Reflection;using System.Xml.Linq;using System.Runtime.Serialization.Json;using GlassBoard;
class NativeControlTests {
    static int checks;static void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}
    static int Main(){
        var id=Guid.NewGuid();IntPtr item=Marshal.AllocHGlobal(628);try{
            Marshal.Copy(new byte[628],0,item,628);byte[] profile=Encoding.Unicode.GetBytes("中文配置\0");Marshal.Copy(profile,0,item,profile.Length);byte[] ssid=Encoding.UTF8.GetBytes("Wi-Fi 中国<&>");Marshal.WriteInt32(item,512,ssid.Length);Marshal.Copy(ssid,0,IntPtr.Add(item,516),ssid.Length);Marshal.WriteInt32(item,604,73);Marshal.WriteInt32(item,608,1);Marshal.WriteInt32(item,612,7);Marshal.WriteInt32(item,616,4);Marshal.WriteInt32(item,620,1);
            var n=NativeWireless.ReadNetwork(item,id);Check(n.Name=="Wi-Fi 中国<&>"&&n.Profile=="中文配置"&&n.Adapter==id.ToString(),"WLAN native offsets/Unicode/profile");Check(n.Signal==73&&n.Secure&&n.Connected&&n.Auth==7&&n.Cipher==4,"WLAN native connection/security flags");
            foreach(int bad in new[]{-1,33}){Marshal.WriteInt32(item,512,bad);bool failed=false;try{NativeWireless.ReadNetwork(item,id);}catch(InvalidDataException){failed=true;}Check(failed,"out of bounds SSID length accepted");}
        }finally{Marshal.FreeHGlobal(item);}
        string name="测试<&>\"网络",password="pass<&>\"word";XNamespace ns="http://www.microsoft.com/networking/WLAN/profile/v1";
        var xml=XElement.Parse(NativeWireless.ProfileXml(name,"profile<&>",password,7,4));Check((string)xml.Element(ns+"name")=="profile<&>","profile XML escaping");Check((string)xml.Descendants(ns+"keyMaterial").Single()==password,"password XML roundtrip");Check((string)xml.Descendants(ns+"hex").Single()==BitConverter.ToString(Encoding.UTF8.GetBytes(name)).Replace("-",""),"SSID UTF8 hex matches actual bytes");Check((string)xml.Descendants(ns+"authentication").Single()=="WPA2PSK"&&(string)xml.Descendants(ns+"encryption").Single()=="AES","security not weakened");
        xml=XElement.Parse(NativeWireless.ProfileXml("open","profile","",1,0));Check(!xml.Descendants(ns+"keyMaterial").Any()&&(string)xml.Descendants(ns+"authentication").Single()=="open","open network needs no secret");
        foreach(var action in new Action[]{()=>NativeWireless.ProfileXml("", "p",password,7,4),()=>NativeWireless.ProfileXml(new string('中',11),"p",password,7,4),()=>NativeWireless.ProfileXml("n","p","short",7,4),()=>NativeWireless.ProfileXml("n","p",new string('x',64),7,4),()=>NativeWireless.ProfileXml("n","p",password,9,4)}){bool refused=false;try{action();}catch(ArgumentException){refused=true;}catch(InvalidOperationException){refused=true;}Check(refused,"unsupported profile accepted");}
        Type audio=typeof(NativeAudio);Check(audio.GetNestedType("ICollection",BindingFlags.NonPublic).GUID==new Guid("0BD7A1BE-7A1A-44DB-8397-CC5392387B5E"),"correct IMMDeviceCollection COM GUID");Check(audio.GetNestedType("IVolume",BindingFlags.NonPublic).GetMethods().Select(m=>m.Name).SequenceEqual(new[]{"RegisterControlChangeNotify","UnregisterControlChangeNotify","GetChannelCount","SetMasterVolumeLevel","SetMasterVolumeLevelScalar","GetMasterVolumeLevel","GetMasterVolumeLevelScalar","SetChannelVolumeLevel","SetChannelVolumeLevelScalar","GetChannelVolumeLevel","GetChannelVolumeLevelScalar","SetMute","GetMute"}),"audio COM method order");
        var wire=new BridgeReply{Version=1,Id=44,Ok=true,Result=new BridgeResult{System=new SystemSnapshot{Audio=new AudioSnapshot{Volume=.5,Muted=false,Outputs=new List<AudioOutput>{new AudioOutput{Id="device-id",Name="扬声器",Selected=true}}},Brightness=72,Radios=new List<RadioSnapshot>{new RadioSnapshot{Kind="Bluetooth",Name="蓝牙",Available=true,Enabled=true}},Errors=new List<string>()}}};using(var buffer=new MemoryStream()){new DataContractJsonSerializer(typeof(BridgeReply)).WriteObject(buffer,wire);buffer.Position=0;var restored=(BridgeReply)new DataContractJsonSerializer(typeof(BridgeReply)).ReadObject(buffer);Check(restored.Id==44&&restored.Result.System.Audio.Outputs[0].Name=="扬声器"&&restored.Result.System.Radios[0].Enabled,"control center wire contract");}
        Console.WriteLine(checks+" checks PASS: production native WLAN parsing and profile/security XML, audio COM ABI and JSON control contract. Windows hardware execution remains separate.");return 0;
    }
}
